sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    if (current.doctor.nil() || current.start_time.nil()) return;

    var newStart = new GlideDateTime(current.start_time);
    var newEnd;

    // Use end_time if provided; otherwise calculate from duration_minutes (default 15 mins)
    if (!current.end_time.nil()) {
        newEnd = new GlideDateTime(current.end_time);
    } else {
        var durationMinutes = parseInt(current.duration_minutes, 10) || 15;
        newEnd = new GlideDateTime(current.start_time);
        newEnd.addSeconds(durationMinutes * 60);
        current.end_time = newEnd.getValue();
    }

    // Two intervals [S1, E1] and [S2, E2] overlap when (S1 < E2) AND (E1 > S2)
    var gr = new GlideRecord('x_2223823_apollo_0_appointment');
    gr.addQuery('doctor', current.doctor);
    gr.addQuery('sys_id', '!=', current.sys_id);
    gr.addQuery('status', 'NOT IN', '6,7'); // Exclude Completed (6) and Cancelled (7)
    gr.addQuery('start_time', '<', newEnd.getValue());
    gr.addQuery('end_time', '>', newStart.getValue());
    gr.setLimit(1);
    gr.query();

    if (gr.next()) {
        current.setAbortAction(true);
        gs.addErrorMessage('The selected doctor already has an active appointment (' + (gr.number || gr.sys_id) + 
            ') overlapping this slot (' + gr.start_time + ' to ' + gr.end_time + '). Double booking is not allowed.');
    }

})(current, previous);
